function minTripleFlips(nums: number[]): number {
  const n = nums.length, w = n - 2;
  let best = -1;
  for (let mask = 0; mask < 1 << w; mask++) {
    const a = nums.slice();
    let count = 0;
    for (let i = 0; i < w; i++) {
      if (mask & (1 << i)) {
        count++;
        for (let j = i; j < i + 3; j++) a[j] ^= 1;
      }
    }
    if (a.every(x => x === 1) && (best === -1 || count < best)) best = count;
  }
  return best;
}

