        w = n - 2
        best = -1
        for mask in range(1 << w):
            a = nums[:]
            count = 0
            for i in range(w):
                if mask >> i & 1:
                    count += 1
                    for j in range(i, i + 3):
                        a[j] ^= 1
            if all(a) and (best == -1 or count < best):
                best = count
        return best

