function minTripleFlips(nums: number[]): number {
  const a = nums.slice();
  const n = a.length;
  let ops = 0;
  for (let i = 0; i + 2 < n; i++) {
    if (a[i] === 0) {
      a[i] ^= 1; a[i + 1] ^= 1; a[i + 2] ^= 1;
      ops++;
    }
  }
  return a[n - 2] === 1 && a[n - 1] === 1 ? ops : -1;
}

